import { LeaveStatuses } from '../../../enums/app/app';
import { expect, test } from '../../../fixtures/pom/test-options';

/**
 * End-to-end cover for the leave approval workflow, the everyday exchange
 * between an employee and their line manager: one requests time off, the other
 * approves it.
 *
 * Both people are generated by the `tempLeaveApprovalUsers` fixture, so the test
 * owns the whole workflow rather than borrowing a pre-existing account for
 * either side. `signInAs` gives each of them a browser context of their own and
 * both stay signed in for the duration, which is what lets the test read as one
 * conversation instead of a sequence of logins.
 *
 * Every record involved is created and removed by the fixtures, so this is
 * isolated test data rather than shared state: `@e2e`, not `@destructive`.
 */
test.describe('leave request approval', () => {
    test.slow();

    test(
        'should let an employee request leave and their supervisor approve it',
        { tag: '@e2e' },
        async ({ tempLeaveApprovalUsers, signInAs }) => {
            const { applicant, supervisor, leaveTypeName, leaveDate } =
                tempLeaveApprovalUsers;

            const employeeSession = await signInAs(applicant);
            const managerSession = await signInAs(supervisor);

            await test.step('GIVEN the employee is on the Apply Leave form', async () => {
                await employeeSession.applyLeavePage.openApplyLeavePage();

                await expect(
                    employeeSession.applyLeavePage.heading
                ).toBeVisible();
            });

            await test.step('WHEN the employee requests leave for an entitled type', async () => {
                await employeeSession.applyLeavePage.applyForLeave({
                    leaveType: leaveTypeName,
                    fromDate: leaveDate,
                    toDate: leaveDate,
                    comment: `Requested by ${applicant.username}`,
                });
            });

            await test.step('THEN the submission is confirmed', async () => {
                await expect(
                    employeeSession.applyLeavePage.successMessage
                ).toBeVisible();
            });

            await test.step('WHEN the manager opens their Leave List', async () => {
                await managerSession.leaveListPage.openLeaveListPage();
            });

            await test.step('THEN it holds that request, awaiting approval', async () => {
                await expect(
                    managerSession.leaveListPage.rowForEmployee(
                        applicant.employeeFullName
                    )
                ).toContainText(LeaveStatuses.PENDING_APPROVAL);
            });

            await test.step('WHEN the manager approves it', async () => {
                await managerSession.leaveListPage.approveLeaveFor(
                    applicant.employeeFullName
                );
            });

            await test.step('THEN the approval is confirmed and the request leaves the pending list', async () => {
                await expect(
                    managerSession.leaveListPage.successMessage
                ).toBeVisible();
                await expect(
                    managerSession.leaveListPage.rowForEmployee(
                        applicant.employeeFullName
                    )
                ).toHaveCount(0);
            });
        }
    );
});
